addEventListener('keydown',e=>{if(document.querySelector('dialog[open]')||e.target?.matches?.('input,select,textarea'))return;if(e.code==='Period'&&training){e.preventDefault();frameAdvance();return;}if(e.code==='Escape'){pause();return;}if(e.code==='KeyM'){if(!e.repeat)mute();return;}if(e.code==='KeyF'){if(!e.repeat)fullscreen();return;}if(state!=='battle')return;if(e.code==='Space'||e.code.startsWith('Arrow'))e.preventDefault();if(!keys.has(e.code))pressed.add(e.code);keys.add(e.code);});addEventListener('keyup',e=>keys.delete(e.code));addEventListener('blur',()=>{keys.clear();Controls.clear();if(state==='battle')pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='battle')pause();});addEventListener('resize',resize);Controls.init({pause,start:()=>{if(state==='menu'&&!$('#home-screen').classList.contains('hidden'))Roster.open($('#battle-mode').value);else start();},getState:()=>state,canResetTraining:()=>training&&!Net.active&&(state==='battle'||state==='pause'),resetTraining});Roster.init();BingoBattle.init();Net.init();GameAudio.init();resize();load();requestAnimationFrame(loop);
// Read-only diagnostics and deterministic combat harness for local verification.
window.AstralEdge={get state(){return state},get fighters(){return fighters},get assetsLoaded(){return loaded},get attacks(){return attacks},start,pause,step:()=>update(),input,hit,attack,ko,get frame(){return frame},get hitstop(){return Math.max(hitstop,...fighters.map(f=>f.hitlag||0))},get attackBoxes(){return attackBoxes},get launch(){return CombatData.launch},setCountdown:v=>countdown=v};

$('#apply-percent').onclick=()=>{if(training&&fighters[1])fighters[1].damage=clamp(Number($('#dummy-percent').value)||0,0,999);};
$('#open-frames').onclick=()=>{renderFrameTable(movesFor(fighters[0]));if(state==='battle')pause();$('#frame-guide').showModal();};$('#close-frames').onclick=()=>$('#frame-guide').close();
function renderFrameTable(moves=attacks){$('#frame-rows').innerHTML=Object.values(moves).map(a=>'<tr><td>'+a.name+'</td><td>'+a.startupFrames+'</td><td>'+(a.counterWindow?'受付 '+a.counterWindow.join('–'):a.spellShots?'発射 '+a.spellShots.join(' / '):a.activeFrames.map(w=>w.start+'–'+w.end).join(' / '))+'</td><td>'+a.recoveryFrames+'</td><td>'+a.landingLagFrames+'</td><td>'+a.totalFrames+'</td></tr>').join('');}renderFrameTable();

function drawDebugColliders(){if(!training||!$('#show-hitboxes').checked)return;ctx.save();for(const p of platforms)if(p.main){const s=StageGeometry.profile(p);path([[p.x,p.y],[p.x+p.w,p.y],[p.x+p.w,p.y+s.lip],[p.x+p.w-s.bevel,p.y+s.depth],[p.x+s.bevel,p.y+s.depth],[p.x,p.y+s.lip]],'#66afff11','#66afff',1);}for(let f of fighters){if(f.respawn||battleWorldHidden(f))continue;for(let h of hurtboxes(f)){let p=CombatSystem.protection(f,h.part);ctx.fillStyle=p.intangible?'#77777744':p.invincible?'#ffe86477':p.armor?'#dd8aff77':'#69ffb944';ctx.strokeStyle=p.intangible?'#aaa':p.invincible?'#ffe864':p.armor?'#dd8aff':'#69ffb9';ctx.lineWidth=1;ctx.beginPath();ctx.arc(h.x,h.y,h.r,0,TAU);ctx.fill();ctx.stroke();}ctx.strokeStyle='#66afff';ctx.strokeRect(f.x-f.character.ecb.radius,f.y-f.character.ecb.height,f.character.ecb.radius*2,f.character.ecb.height);for(let b of attackBoxes(f)){ctx.globalAlpha=.55;line([[b.x1,b.y1],[b.x2,b.y2]],f.attack.type==='grab'?'#ca63ff':'#ff4563',b.radius*2);ctx.globalAlpha=1;}}ctx.restore();}
$('#frame-step').onclick=frameAdvance;$('#debug-pause').onclick=()=>{if(!training)return;state=state==='battle'?'pause':'battle';$('#pause').classList.add('hidden');};$('#slow-motion').onchange=e=>simulationSpeed=Number(e.target.value);



